import { execFile } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { promisify } from 'node:util';
const execFileAsync = promisify(execFile);
const BYTES_PER_MIB = 1024 * 1024;
/**
 * `child_process` defaults to a 1 MiB stdout cap; `npm audit --json` can exceed
 * that for very large lockfiles.
 */
export const MAX_NPM_AUDIT_JSON_BUFFER = 20 * BYTES_PER_MIB;
const ERR_CHILD_PROCESS_STDIO_MAXBUFFER = 'ERR_CHILD_PROCESS_STDIO_MAXBUFFER';
function resolveExecErrorCode(e) {
    if (e.code === 'ENOENT') {
        return 127;
    }
    if (e.code && /^\d+$/.test(e.code)) {
        return Number(e.code);
    }
    return 1;
}
function syntheticError(message, code, options) {
    return {
        source: JSON.stringify({
            error: {
                message,
                code,
                ...(options.stderr && { detail: options.stderr }),
            },
            ...(options.stdout && { rawStdout: options.stdout }),
        }),
        exitCode: options.exitCode,
        skipped: false,
    };
}
export async function runNpmAuditJson(auditRoot) {
    const pkgPath = path.join(auditRoot, 'package.json');
    const lockPath = path.join(auditRoot, 'package-lock.json');
    if (!fs.existsSync(pkgPath) || !fs.existsSync(lockPath)) {
        return { source: '', exitCode: 0, skipped: true };
    }
    try {
        const { stdout } = await execFileAsync('npm', ['audit', '--json'], {
            cwd: auditRoot,
            encoding: 'utf8',
            maxBuffer: MAX_NPM_AUDIT_JSON_BUFFER,
            // On Windows `npm` is `npm.cmd`, which CreateProcess cannot resolve
            // without a shell, so execFile would fail with a misleading ENOENT.
            shell: true,
        });
        return {
            source: stdout,
            exitCode: 0,
            skipped: false,
        };
    }
    catch (err) {
        const e = err;
        const stdout = typeof e.stdout === 'string' ? e.stdout : String(e.stdout ?? '');
        const stderr = typeof e.stderr === 'string' ? e.stderr : String(e.stderr ?? '');
        const exitCode = resolveExecErrorCode(e);
        if (e.code === 'ENOENT' || exitCode === 127) {
            return syntheticError('npm is not available or not in PATH', 'ENOENT', {
                stderr,
                exitCode: 127,
                stdout: stdout || undefined,
            });
        }
        if (e.code === ERR_CHILD_PROCESS_STDIO_MAXBUFFER) {
            return syntheticError('npm audit JSON output exceeded the configured maxBuffer; increase the limit or reduce dependency tree size', ERR_CHILD_PROCESS_STDIO_MAXBUFFER, { stderr, exitCode, stdout: stdout || undefined });
        }
        if (stdout.trim() !== '') {
            return { source: stdout, exitCode, skipped: false };
        }
        return syntheticError('npm audit failed with no JSON output', 'AUDIT_FAILED', {
            stderr,
            exitCode,
            stdout: stdout || undefined,
        });
    }
}
